package com.losgram.app;
import android.app.Activity; import android.os.Bundle; import android.webkit.WebView; import android.webkit.WebViewClient; import android.webkit.WebChromeClient; import android.graphics.Color;
public class MainActivity extends Activity { private WebView web; public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(14,22,33));getWindow().setNavigationBarColor(Color.rgb(14,22,33));web=new WebView(this);web.setBackgroundColor(Color.rgb(14,22,33));web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.setWebViewClient(new WebViewClient());web.setWebChromeClient(new WebChromeClient());setContentView(web);web.loadUrl("https://losgram.onrender.com");} public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else super.onBackPressed();}}
